{
  "technical_and_design_decisions": [
    "Extend the existing JUnit-based acceptance test harness (Spring Cloud Stream app starters acceptance tests) rather than building a new framework.",
    "Run the modules under test as standalone Spring Boot uber-jars using a local deployer, and drive end-to-end flows with an HTTP source and log/metric verification.",
    "Provide external dependencies via Testcontainers/embedded servers: GreenMail for the mail sink, Hadoop MiniDFSCluster (or Testcontainers HDFS) for hdfs-dataset, and an in-memory/embedded metrics store for gauge, aggregate-counter, and field-value-counter.",
    "Write tests in Java 17 with Spring Boot Test, AssertJ, and Awaitility for asynchronous assertions.",
    "Activate acceptance tests through a dedicated Maven/Gradle profile that the CI build invokes on every build, with tests tagged so they can be selected by the pipeline.",
    "Keep the modules under test unchanged; the increment adds test code, test fixtures, and CI configuration only."
  ],
  "assumptions": [
    "An existing acceptance-test module/framework and CI system (e.g., Jenkins or Concourse) already exist and only need to be extended, not created from scratch.",
    "One developer performs all work; estimates are work-hours, not elapsed calendar time.",
    "Docker is available on the developer machine and CI agents so Testcontainers-based dependencies can run.",
    "Each user story is satisfied by a small suite of acceptance tests (roughly 3-8 scenarios per module) covering happy path, key configuration options, and representative failure/edge cases.",
    "Estimates include test design, implementation, local debugging, code review rework, CI wiring, and minimal documentation; they exclude procurement of new infrastructure and fixes to defects discovered in the modules under test.",
    "The 'script' and 'scripts' processors are treated as two separate modules within user story U2, each with its own test suite."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Test infrastructure setup and framework familiarization",
      "activity_description": "Review the existing acceptance test harness, set up the local development environment (Java 17, Docker/Testcontainers), and verify the harness runs end-to-end locally.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "CI build integration design and configuration",
      "activity_description": "Define and configure the CI build stage/profile so the new acceptance tests execute as part of every CI build, including reporting of test results.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3",
      "activity_name": "Acceptance tests for json-tuple processor (U1)",
      "activity_description": "Implement acceptance tests validating JSON-to-tuple transformation: happy path, nested fields, and malformed input handling, verified via deployed stream output.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "Acceptance tests for script processor (U2a)",
      "activity_description": "Implement acceptance tests for the script processor covering script evaluation (e.g., Groovy/JavaScript), variable binding, and script error handling.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A5",
      "activity_name": "Acceptance tests for scripts processor (U2b)",
      "activity_description": "Implement acceptance tests for the scripts processor covering mapping of payload variables to script functions and multi-function script configurations.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A6",
      "activity_name": "Acceptance tests for splitter processor (U3)",
      "activity_description": "Implement acceptance tests validating message splitting: collection splitting, delimiter/expression-based splitting, and correlated output message verification.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7",
      "activity_name": "Acceptance tests for gauge sink (U4)",
      "activity_description": "Implement acceptance tests validating gauge metric publication to the configured metrics store, including value submission and metric retrieval verification.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8",
      "activity_name": "Acceptance tests for aggregate-counter sink (U5)",
      "activity_description": "Implement acceptance tests validating aggregated counting over time windows and buckets, including increment/store/retrieve scenarios.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A9",
      "activity_name": "Acceptance tests for field-value-counter sink (U6)",
      "activity_description": "Implement acceptance tests validating counting of occurrences of named field values from incoming payloads and querying the resulting counts.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A10",
      "activity_name": "Acceptance tests for hdfs-dataset sink (U7)",
      "activity_description": "Implement acceptance tests against an embedded/Testcontainers HDFS cluster validating dataset writing, file rollover, partitioning options, and read-back verification.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A11",
      "activity_name": "Acceptance tests for mail sink (U8)",
      "activity_description": "Implement acceptance tests using an embedded SMTP server (GreenMail) validating email delivery, recipients, subject/body content, and expression-based fields.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A12",
      "activity_name": "Test stabilization, debugging, and code review rework",
      "activity_description": "Stabilize flaky asynchronous tests (timeouts, Awaitility tuning), debug CI-only failures, and address code review feedback across all suites.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A13",
      "activity_name": "Documentation and handover",
      "activity_description": "Document how to run the new acceptance tests locally and in CI, update README/build docs, and hand over the increment.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 192
  }
}
